import{_ as r,o as d,c as e,ag as o}from"./chunks/framework.D2veAa-g.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-指令流水线","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-指令流水线"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/CPU与指令系统/指令流水线.md","filePath":"综合知识/系统基础/计算机组成/CPU与指令系统/指令流水线.md","lastUpdated":null}'),a={name:"综合知识/系统基础/计算机组成/CPU与指令系统/指令流水线.md"};function n(s,t,l,h,i,g){return d(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="指令流水线-★" tabindex="-1">指令流水线 ★ <a class="header-anchor" href="#指令流水线-★" aria-label="Permalink to &quot;指令流水线 ★&quot;">​</a></h3><blockquote><p>将指令分成不同段，每段由不同部件并行处理。</p></blockquote><p><strong>RISC 流水线三种技术：</strong></p><table tabindex="0"><thead><tr><th>技术</th><th>核心理念</th><th>本质</th></tr></thead><tbody><tr><td><strong>超流水线</strong></td><td>细化流水、增加级数、提高主频</td><td><strong>时间换空间</strong></td></tr><tr><td><strong>超标量</strong></td><td>多条流水线同时执行多个处理</td><td><strong>空间换时间</strong></td></tr><tr><td><strong>超长指令字（VLIW）</strong></td><td>软件调度并行，简化硬件</td><td>软件发挥主要作用</td></tr></tbody></table><h4 id="超线程技术-hyper-threading-★" tabindex="-1">超线程技术（Hyper-Threading）★ <a class="header-anchor" href="#超线程技术-hyper-threading-★" aria-label="Permalink to &quot;超线程技术（Hyper-Threading）★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>超线程让一个物理核心模拟两个逻辑核心</strong>，共享执行资源，提高 CPU 并行计算能力。</p></blockquote><ul><li>一个物理核心配备两套寄存器组和中断逻辑，操作系统看到&quot;两个核心&quot;</li><li>共享物理执行单元（ALU、Cache 等），并非真正的双核</li><li>适合多线程负载，单线程密集型收益有限</li><li>属于提高 CPU 并行计算能力的技术（区别于加密/压缩/缓存技术）</li></ul><p><strong>流水线核心公式：</strong></p><table tabindex="0"><thead><tr><th>指标</th><th>公式</th></tr></thead><tbody><tr><td><strong>流水线周期</strong></td><td>各段中<strong>执行时间最长的段</strong>的时间</td></tr><tr><td><strong>执行时间</strong></td><td>1条指令总执行时间 +（总指令条数 - 1）× 流水线周期</td></tr><tr><td><strong>吞吐率</strong></td><td>指令条数 / 流水线执行时间</td></tr><tr><td><strong>加速比</strong></td><td>不使用流水线执行时间 / 使用流水线执行时间</td></tr></tbody></table>',10)])])}const p=r(a,[["render",n]]);export{c as __pageData,p as default};
